package org.eclipse.rdf4j.query.algebra.evaluation.function.geosparql;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.GEO;
import org.eclipse.rdf4j.model.vocabulary.GEOF;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.algebra.FunctionCall;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.GenericPlanNode;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;

/**
 * Review reproducer: GeoSPARQL filters (and conjuncts next to them) are no longer relocated by FilterOptimizer on
 * MemoryStore because ScalarEvaluationEffects classifies non-core-jar functions as UNKNOWN.
 */
public class GeoFilterPlacementReviewReproTest {

	private static final String PREFIXES = "PREFIX geo: <http://www.opengis.net/ont/geosparql#>\n"
			+ "PREFIX geof: <http://www.opengis.net/def/function/geosparql/>\n"
			+ "PREFIX ex: <http://example.org/>\n";

	private static final String POLY = "\"POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))\"^^geo:wktLiteral";

	@Test
	public void geofFunctionIsClassifiedUnknown() {
		FunctionCall call = new FunctionCall(GEOF.SF_WITHIN.stringValue(), Var.of("wkt"),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral("POINT(1 1)", GEO.WKT_LITERAL)));
		assertEquals(ScalarEvaluationEffects.Effect.REPEATABLE, ScalarEvaluationEffects.effectOf(call));
	}

	@Test
	public void geoFilterIsPushedToWktPattern() throws Exception {
		String query = "SELECT ?s WHERE { ?s ex:name ?n . ?s ex:type ?t . ?s geo:asWKT ?wkt . FILTER(geof:sfWithin(?wkt, "
				+ POLY + ")) }";
		List<String> filterArgs = filterArgTypes(query);
		assertTrue(filterArgs.stream().anyMatch(t -> t.startsWith("StatementPattern")),
				"develop pushes the geof filter onto the asWKT pattern; filter args were " + filterArgs);
	}

	@Test
	public void cheapConjunctNextToGeoFilterIsPushedReversed() throws Exception {
		String query = "SELECT ?s WHERE { ?s ex:name ?n . ?s ex:type ?t . ?s geo:asWKT ?wkt . FILTER(STRSTARTS(?n, \"n1\") && geof:sfWithin(?wkt, "
				+ POLY + ")) }";
		List<String> filterArgs = filterArgTypes(query);
		assertTrue(filterArgs.stream().filter(t -> t.startsWith("StatementPattern")).count() >= 1,
				"develop pushes the STRSTARTS conjunct onto the name pattern; filter args were " + filterArgs);
	}

	@Test
	public void cheapConjunctNextToGeoFilterIsPushed() throws Exception {
		String query = "SELECT ?s WHERE { ?s ex:name ?n . ?s ex:type ?t . ?s geo:asWKT ?wkt . FILTER(geof:sfWithin(?wkt, "
				+ POLY + ") && STRSTARTS(?n, \"n1\")) }";
		List<String> filterArgs = filterArgTypes(query);
		assertTrue(filterArgs.stream().filter(t -> t.startsWith("StatementPattern")).count() >= 1,
				"develop pushes the STRSTARTS conjunct onto the name pattern; filter args were " + filterArgs);
	}

	private List<String> filterArgTypes(String query) throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			StringBuilder data = new StringBuilder(
					"@prefix ex: <http://example.org/> . @prefix geo: <http://www.opengis.net/ont/geosparql#> .\n");
			for (int i = 0; i < 50; i++) {
				data.append("ex:s").append(i).append(" ex:name \"n").append(i).append("\" ; ex:type ex:T")
						.append(i % 5)
						.append(" ; geo:asWKT \"POINT(")
						.append(i)
						.append(' ')
						.append(i)
						.append(")\"^^geo:wktLiteral .\n");
			}
			conn.add(new StringReader(data.toString()), "", RDFFormat.TURTLE);
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIXES + query);
			Explanation explanation = tupleQuery.explain(Explanation.Level.Optimized);
			System.out.println(explanation);
			List<String> result = new ArrayList<>();
			collectFilterArgs(explanation.toGenericPlanNode(), result);
			return result;
		} finally {
			repository.shutDown();
		}
	}

	private static void collectFilterArgs(GenericPlanNode node, List<String> result) {
		List<GenericPlanNode> children = node.getPlans();
		if (node.getType() != null && node.getType().startsWith("Filter") && children != null
				&& !children.isEmpty()) {
			result.add(children.get(children.size() - 1).getType());
		}
		if (children != null) {
			for (GenericPlanNode child : children) {
				collectFilterArgs(child, result);
			}
		}
	}
}
